mutations.before:
  setRail({
    label: messages.previewLegend,
    // `PlayheadHost` is mounted INSIDE the published subtree, not around the
    // editor's column: the seconds move on every pointermove, and publishing a
    // playhead-dependent element per frame would write context per frame.
    // Keeping the state below the publish point means a scrub writes none.
    content: <PlayheadHost durationSec={previewDurationSec} rail={railSlot} />,
  });
}, [railSlot, previewDurationSec, setRail, unknownId, failedRouteId]);

mutations.after:
  if (columnView === "yaml") {
    setRail(null);
    return;
  }
  setRail({
    label: messages.previewLegend,
    // `PlayheadHost` is mounted INSIDE the published subtree, not around the
    // editor's column: the seconds move on every pointermove, and publishing a
    // playhead-dependent element per frame would write context per frame.
    // Keeping the state below the publish point means a scrub writes none.
    content: <PlayheadHost durationSec={previewDurationSec} rail={railSlot} />,
  });
}, [columnView, railSlot, previewDurationSec, setRail, unknownId, failedRouteId]);

mutations.before:
type ColumnView = "editor" | "yaml";

/**
 * The positions, in the order they are offered. The control is rendered from this
 * list rather than from two hand-written buttons, so a third position is one entry
 * plus the records below — and the count test reads the DOM, not this array.
 */
const COLUMN_VIEWS: readonly ColumnView[] = ["editor", "yaml"];

mutations.after:
type ColumnView = "editor" | "yaml" | "validate";

/**
 * The positions, in the order they are offered. The control is rendered from this
 * list rather than from two hand-written buttons, so a third position is one entry
 * plus the records below — and the count test reads the DOM, not this array.
 */
const COLUMN_VIEWS: readonly ColumnView[] = ["editor", "yaml", "validate"];
